<form method="get" action="/csi/reports" class="report-filters report-filters--reference" aria-label="Filtros de reportes">
  <input type="hidden" name="tab" value="<?= $e($tab) ?>">
  <div class="report-filters__main">
    <div class="report-date">
      <span class="report-field-label">Período</span>
      <details id="report-period" class="report-period">
        <summary><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 10h18"/></svg><span><?= $e($start->format('d/m/Y')) ?> – <?= $e($end->format('d/m/Y')) ?></span><span aria-hidden="true">⌄</span></summary>
        <div class="report-period__popover"><label for="report-from">Desde</label><input id="report-from" name="from" type="date" value="<?= $e((string) ($filters['from'] ?? '')) ?>"><label for="report-to">Hasta</label><input id="report-to" name="to" type="date" value="<?= $e((string) ($filters['to'] ?? '')) ?>"><button type="submit">Aplicar período</button></div>
      </details>
    </div>
    <?php foreach (['area' => ['Oficina', 'areas', 'Todas las oficinas'], 'technician' => ['Personal', 'technicians', 'Todo el personal'], 'category' => ['Tipo de problema', 'categories', 'Todas las categorías'], 'status' => ['Estado', 'statuses', 'Todos']] as $key => [$label, $source, $emptyLabel]): ?>
      <div><label for="report-<?= $key ?>"><?= $label ?></label><select id="report-<?= $key ?>" name="<?= $key ?>" onchange="this.form.requestSubmit()"><option value=""><?= $emptyLabel ?></option><?php foreach ($filterOptions[$source] as $option): ?><option value="<?= (int) $option['id'] ?>" <?= (string) ($filters[$key] ?? '') === (string) $option['id'] ? 'selected' : '' ?>><?= $e($option['name']) ?></option><?php endforeach; ?></select></div>
    <?php endforeach; ?>
    <div class="report-filter-options"><span class="report-field-label">Opciones</span><details class="report-more"><summary><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M3 5h18l-7 8v5l-4 2v-7z"/></svg>Más filtros</summary><div><label for="report-search">Código o asunto</label><input id="report-search" name="search" maxlength="100" value="<?= $e((string) ($filters['search'] ?? '')) ?>"><label for="report-priority">Prioridad</label><select id="report-priority" name="priority"><option value="">Todas</option><?php foreach ($filterOptions['priorities'] as $option): ?><option value="<?= (int) $option['id'] ?>" <?= (string) ($filters['priority'] ?? '') === (string) $option['id'] ? 'selected' : '' ?>><?= $e($option['name']) ?></option><?php endforeach; ?></select><label for="report-assignment">Asignación</label><select id="report-assignment" name="assignment"><option value="">Todas</option><option value="assigned" <?= ($filters['assignment'] ?? '') === 'assigned' ? 'selected' : '' ?>>Asignadas</option><option value="unassigned" <?= ($filters['assignment'] ?? '') === 'unassigned' ? 'selected' : '' ?>>Sin asignar</option></select><?php require __DIR__ . '/csi-report-extra-filters.php'; ?><button type="submit">Aplicar filtros</button></div></details></div>
    <div class="report-filter-export"><span class="report-field-label">Generar informe</span><details class="report-export"><summary><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M12 3v12m-4-4 4 4 4-4M4 18v3h16v-3"/></svg>Exportar reporte <span aria-hidden="true">⌄</span></summary><div><a href="/csi/reports.csv<?= $e($exportSuffix) ?>">Descargar CSV</a><a href="/csi/reports.pdf<?= $e($exportSuffix) ?>">Descargar PDF</a></div></details></div>
  </div>
  <div class="report-filters__bottom"><strong>Períodos rápidos</strong><a href="<?= $e($quickUrl($today->modify('first day of this month')->format('Y-m-d'), $today->format('Y-m-d'))) ?>">Este mes</a><a href="<?= $e($quickUrl($today->modify('first day of last month')->format('Y-m-d'), $today->modify('last day of last month')->format('Y-m-d'))) ?>">Mes anterior</a><a href="<?= $e($quickUrl($today->modify('first day of -2 months')->format('Y-m-d'), $today->format('Y-m-d'))) ?>">Últimos 3 meses</a><a href="<?= $e($quickUrl($today->modify('-14 days')->format('Y-m-d'), $today->format('Y-m-d'))) ?>">Esta quincena</a><button type="button" onclick="document.getElementById('report-period').open=true;document.getElementById('report-from').focus()">Rango personalizado</button><span class="report-period-label">Datos del <?= $e($start->format('d/m/Y')) ?> al <?= $e($end->format('d/m/Y')) ?></span><a class="report-clear" href="/csi/reports">Limpiar filtros</a></div>
  <?php if ($filterErrors !== []): ?><p class="report-error" role="alert"><?= $e(implode(' ', $filterErrors)) ?></p><?php endif; ?>
</form>
